/**
 * `convert` subcommand: translate a sampled Notion data source (public API
 * shapes: schema `properties`, query `results`) into the dev shell's local
 * JSON data source format, validate the result, and print it to stdout.
 * `ntn workers customblocks sample` pipes through this via stdin; it also runs
 * standalone: `npx @notionhq/custom-blocks-dev-shell convert --in sample.json`.
 */
import { readFileSync } from "node:fs";
import * as v from "valibot";
import { convertPublicApiPropertyValue, isDataSourceValue, matchesPropertyType, } from "./convert-values.js";
import { NOTION_PROPERTY_TYPES, sourceFileSchema } from "./data-sources.js";
import { formatUnknownError } from "./errors.js";
import { claimUniqueKey, parseCliArgs, slugify } from "./utils.js";
const SUPPORTED_TYPES = new Set(NOTION_PROPERTY_TYPES);
/** The spelling of "text" in the local file format. */
const UNSUPPORTED_TYPE_FALLBACK = "rich_text";
export function parseConvertArgs(argv) {
    const args = {
        input: undefined,
        name: undefined,
    };
    const rejectUnknown = (arg) => {
        throw new Error(`Unknown convert option "${arg}". Supported: --in <file>, --name <name>.`);
    };
    parseCliArgs({
        argv,
        handlers: {
            "--in": value => {
                args.input = value;
            },
            "--name": value => {
                args.name = value;
            },
        },
        onUnknown: rejectUnknown,
        // This command accepts no positional arguments.
        onPositional: rejectUnknown,
    });
    return args;
}
const sampleInputSchema = v.pipe(v.looseObject({
    name: v.optional(v.string()),
    properties: v.optional(v.record(v.string(), v.looseObject({ type: v.string() }))),
    results: v.optional(v.array(v.looseObject({
        id: v.string(),
        properties: v.optional(v.record(v.string(), v.unknown())),
    }))),
}), v.check(input => input.properties !== undefined || input.results !== undefined, "expected a schema under `properties` and/or sampled pages under `results`"));
/**
 * Convert a sampled data source (public API shapes) into a local data source
 * object. The input carries the schema under `properties` and/or sampled
 * pages under `results` (query output verbatim). The emitted object always
 * carries a `schema` — taken from `properties` when present, otherwise
 * inferred from the row values — because the shell derives table columns and
 * bindings from the schema alone.
 */
export function convertSample(input, overrides = {}) {
    const parsed = v.safeParse(sampleInputSchema, input);
    if (!parsed.success) {
        const issue = parsed.issues[0];
        const path = v.getDotPath(issue);
        throw new Error(`Input is not a sampled data source: ${path ? `${path}: ` : ""}${issue.message}`);
    }
    const sample = parsed.output;
    const warnings = [];
    const mappings = buildPropertyMappings(sample.properties, sample.results, warnings);
    const name = overrides.name ?? (sample.name || undefined);
    const schema = {};
    for (const mapping of mappings.values()) {
        schema[mapping.key] = { name: mapping.name, type: mapping.type };
    }
    const source = {
        type: "syncedFromProd",
        ...(name !== undefined ? { name } : {}),
        schema,
        rows: (sample.results ?? []).map(row => convertRow(row, mappings)),
    };
    validateSource(source);
    return { source, warnings };
}
/**
 * One mapping per public property name. For schema-only and full samples the
 * mappings come from `properties`; for rows-only samples they are derived
 * from the `type` field each row value carries.
 */
function buildPropertyMappings(properties, sampledRows, warnings) {
    const mappings = new Map();
    // `id` is the row identifier; a property named "ID" must not overwrite it.
    const usedKeys = new Set(["id"]);
    const add = (propertyName, publicType) => {
        if (mappings.has(propertyName)) {
            return;
        }
        const unsupported = !SUPPORTED_TYPES.has(publicType);
        if (unsupported) {
            warnings.push(`Property ${JSON.stringify(propertyName)}: public API type ` +
                `${JSON.stringify(publicType)} is not supported by custom blocks; ` +
                `converted to text ("${UNSUPPORTED_TYPE_FALLBACK}") with the ` +
                `placeholder value ${JSON.stringify(`unsupported type: ${publicType}`)}.`);
        }
        mappings.set(propertyName, {
            key: claimUniqueKey(slugify(propertyName) ?? "property", usedKeys),
            name: propertyName,
            type: unsupported ? UNSUPPORTED_TYPE_FALLBACK : publicType,
            publicType,
            unsupported,
        });
    };
    for (const [propertyName, property] of Object.entries(properties ?? {})) {
        add(propertyName, property.type);
    }
    for (const row of sampledRows ?? []) {
        for (const [propertyName, value] of Object.entries(row.properties ?? {})) {
            const publicType = value?.type;
            if (typeof publicType === "string") {
                add(propertyName, publicType);
            }
        }
    }
    return mappings;
}
function convertRow(row, mappings) {
    const converted = { id: row.id };
    for (const [propertyName, value] of Object.entries(row.properties ?? {})) {
        const mapping = mappings.get(propertyName);
        if (mapping === undefined) {
            continue;
        }
        if (mapping.unsupported) {
            converted[mapping.key] = `unsupported type: ${mapping.publicType}`;
            continue;
        }
        const local = convertPublicApiPropertyValue(mapping.publicType, value);
        if (local !== undefined) {
            converted[mapping.key] = local;
        }
    }
    return converted;
}
/**
 * Validate the built source the same way the dev shell will at spin-up, plus
 * a row-value pass the loader doesn't do: every emitted value must match its
 * declared schema type. Failures here are conversion bugs or malformed input;
 * the command must never print a file the shell would reject.
 */
export function validateSource(source) {
    const hasSchema = source.schema !== undefined;
    const result = v.safeParse(sourceFileSchema, source);
    if (!result.success) {
        const issue = result.issues[0];
        const path = v.getDotPath(issue);
        throw new Error(`Converted data source is invalid: ${path ? `${path}: ` : ""}${issue.message}`);
    }
    const schema = (source.schema ?? {});
    const rows = (source.rows ?? []);
    const issues = [];
    for (const row of rows) {
        for (const [key, value] of Object.entries(row)) {
            if (key === "id") {
                continue;
            }
            const declared = hasSchema ? schema[key] : undefined;
            if (hasSchema && declared === undefined) {
                issues.push(`row ${JSON.stringify(row.id)}: ${JSON.stringify(key)} is not in the schema`);
                continue;
            }
            const matches = declared
                ? matchesPropertyType(value, declared.type)
                : isDataSourceValue(value);
            if (!matches) {
                issues.push(`row ${JSON.stringify(row.id)}: ${JSON.stringify(key)} does not match ${declared ? `type ${JSON.stringify(declared.type)}` : "any supported value shape"}`);
            }
        }
    }
    if (issues.length > 0) {
        throw new Error(`Converted rows are invalid: ${issues.join("; ")}`);
    }
}
export async function runConvert(argv) {
    const args = parseConvertArgs(argv);
    let raw;
    if (args.input !== undefined) {
        try {
            raw = readFileSync(args.input, "utf-8");
        }
        catch (error) {
            throw new Error(`Could not read ${args.input}: ${formatUnknownError(error)}`);
        }
    }
    else {
        if (process.stdin.isTTY) {
            throw new Error("No input: pipe `ntn workers customblocks sample` output to convert, or pass --in <file>.");
        }
        raw = readFileSync(0, "utf-8");
    }
    let parsed;
    try {
        parsed = JSON.parse(raw);
    }
    catch (error) {
        throw new Error(`Input is not valid JSON — ${formatUnknownError(error)}`);
    }
    const { source, warnings } = convertSample(parsed, {
        ...(args.name !== undefined ? { name: args.name } : {}),
    });
    for (const warning of warnings) {
        console.warn(warning);
    }
    process.stdout.write(`${JSON.stringify(source, null, "\t")}\n`);
}
